package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var tempRec TempRec
var tempFile *os.File
var tempReader *bufio.Reader
var inputDone bool

func storeDecimal(v decimal.Decimal, intDigits, decDigits int) decimal.Decimal {
	if intDigits+decDigits == 0 {
		return decimal.Zero
	}
	modBase := decimal.New(1, int32(intDigits+decDigits))
	unscaled := v.Shift(int32(decDigits))
	signNeg := unscaled.Sign() < 0
	abs := unscaled.Abs()
	rem := abs.Mod(modBase)
	if signNeg {
		rem = rem.Neg()
	}
	return rem.Shift(int32(-decDigits))
}

func formatZZ9Dot9(v decimal.Decimal) string {
	intDigits := 3
	decDigits := 1
	// MOVE truncation for edited field: keep low order digits
	v = storeDecimal(v, intDigits, decDigits)
	abs := v.Abs()
	unscaled := abs.Shift(int32(decDigits))
	s := unscaled.StringFixed(0) // integer string, no sign
	// pad
	totalDigits := intDigits + decDigits
	if len(s) < totalDigits {
		s = strings.Repeat("0", totalDigits-len(s)) + s
	} else if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	intPart := s[:intDigits]
	decPart := s[intDigits:]

	resInt := []byte(intPart)
	suppressed := true
	for i := 0; i < intDigits; i++ {
		isMandatory := i == intDigits-1
		c := intPart[i]
		if suppressed {
			if c == '0' && !isMandatory {
				resInt[i] = ' '
			} else {
				resInt[i] = c
				suppressed = false
			}
		} else {
			resInt[i] = c
		}
	}
	return string(resInt) + "." + decPart
}

func formatMinusZZ9Dot99(v decimal.Decimal) string {
	intDigits := 3
	decDigits := 2
	// v already stored with truncation, but ensure
	// keep as is; if formatting directly we also truncate
	// but caller has stored; we still handle overflow in formatter for safety
	// use absolute for digit extraction but keep sign char from original v
	signChar := ' '
	if v.Sign() < 0 {
		signChar = '-'
	}
	abs := v.Abs()
	// overflow already handled in store, but if not, handle:
	// we extract digits after taking absolute and applying store truncation to absolute?
	// To keep consistent with COBOL, truncation is on signed value; absolute part is same.
	// So apply store to absolute and re-apply sign char separately is ok.
	truncAbs := storeDecimal(abs, intDigits, decDigits)
	unscaled := truncAbs.Shift(int32(decDigits))
	s := unscaled.StringFixed(0)
	totalDigits := intDigits + decDigits
	if len(s) < totalDigits {
		s = strings.Repeat("0", totalDigits-len(s)) + s
	} else if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	intPart := s[:intDigits]
	decPart := s[intDigits:]

	resInt := []byte(intPart)
	suppressed := true
	for i := 0; i < intDigits; i++ {
		isMandatory := i == intDigits-1
		c := intPart[i]
		if suppressed {
			if c == '0' && !isMandatory {
				resInt[i] = ' '
			} else {
				resInt[i] = c
				suppressed = false
			}
		} else {
			resInt[i] = c
		}
	}
	return string([]byte{byte(signChar)}) + string(resInt) + "." + decPart
}

func formatPIC99(v int64) string {
	// high-order truncation to 2 digits
	v = v % 100
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

func parsePIC9V9(s string, decDigits int32) decimal.Decimal {
	// s is digit characters possibly with spaces
	// keep only digits, treat empty as 0
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		clean = "0"
	}
	d, err := decimal.NewFromString(clean)
	if err != nil {
		d = decimal.Zero
	}
	return d.Shift(-decDigits)
}

func READ_PARA() {
	line, err := tempReader.ReadString('\n')
	if err != nil {
		// EOF or other: check if line has content
		if len(line) == 0 {
			WsEofFlag = "Y"
			inputDone = true
			return
		}
		// partial last line without newline, still process it then next read will be EOF
		// fall through to process line
	} else {
		// strip newline endings \r\n or \n
		if strings.HasSuffix(line, "\r\n") {
			line = strings.TrimSuffix(line, "\r\n")
		} else if strings.HasSuffix(line, "\n") {
			line = strings.TrimSuffix(line, "\n")
		}
		// for normal read we have stripped; for EOF case we haven't yet
		// handle EOF case where we had err==io.EOF but line contains data with newline already stripped? ReadString returns data up to EOF without newline
		// In that branch we need to strip possible \r
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		// successful read, continue to parse
		goto parse
	}
	// EOF branch with line content
	if strings.HasSuffix(line, "\r\n") {
		line = strings.TrimSuffix(line, "\r\n")
	} else if strings.HasSuffix(line, "\n") {
		line = strings.TrimSuffix(line, "\n")
	}
	if strings.HasSuffix(line, "\r") {
		line = strings.TrimSuffix(line, "\r")
	}
parse:
	if err != nil && len(line) == 0 {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	// pad to 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	tempRec.TcSensor = line[0:4]
	rawF := line[4:8]
	tempRec.TcF = parsePIC9V9(rawF, 1)

	// if this was an EOF-triggered partial line, next read will be EOF; but we set not done yet
	// need to distinguish: if err != nil and we parsed a line, we must remember that next read is EOF.
	// We will keep inputDone false now; next call will set true.
	if err != nil {
		// we have consumed the last line; set a flag so next READ_PARA will hit EOF?
		// We need to not set inputDone now, but we need to ensure tempReader will return EOF next time.
		// Since we already consumed err==EOF, next call will get 0, EOF.
		// So leave inputDone false.
		// But we must prevent losing the fact that we just read last line: we have it.
		// So do not set inputDone.
		// However if the line was empty due to EOF, we already returned.
		// For a final line that had newline, err==nil so we are fine.
		// For final line without newline, we parsed it; keep inputDone false.
		// To ensure next call returns EOF, we leave reader as is.
		// But if we want to avoid infinite loop, we need to have next call detect EOF.
		// That's fine.
		if len(line) != 0 && err != nil {
			// we need to make sure next READ_PARA will get EOF; it will.
		}
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	tmp := tempRec.TcF.Sub(decimal.NewFromInt(32))
	tmp = tmp.Mul(decimal.NewFromInt(5))
	tmp = tmp.Div(decimal.NewFromInt(9))
	rounded := tmp.Round(2)
	WsC = storeDecimal(rounded, 3, 2)
	if WsC.Sign() < 0 {
		WsFreeze = WsFreeze + 1
		// truncation to PIC 99
		WsFreeze = WsFreeze % 100
	}
	WsCount = WsCount + 1
	WsCount = WsCount % 100

	WsFEd = formatZZ9Dot9(tempRec.TcF)
	WsCEd = formatMinusZZ9Dot99(WsC)
	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)
	READ_PARA()
}

func main() {
	var err error
	tempFile, err = os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		tempFile = nil
		tempReader = bufio.NewReader(strings.NewReader(""))
	} else {
		defer tempFile.Close()
		tempReader = bufio.NewReader(tempFile)
	}
	if tempReader == nil {
		tempReader = bufio.NewReader(strings.NewReader(""))
	}
	WsEofFlag = "N"
	inputDone = false
	// MAIN-PARA
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}
